import { useMemo, useState } from 'react';
import api from '../content/api-1.0.1.json';

// API index generated by introspecting the published qector-decoder-v3 wheel
// (public names, signatures, first docstring paragraph, public methods).
// Regenerate for each release; never edit by hand.

interface ApiItem { name: string; kind: string; signature: string; summary: string; methods: { name: string; signature: string }[] }

const KINDS = ['class', 'function', 'module'] as const;

export default function ApiIndex() {
  const [query, setQuery] = useState('');
  const [kind, setKind] = useState<string>('all');
  const items = api.items as ApiItem[];
  const shown = useMemo(() => {
    const q = query.trim().toLowerCase();
    return items.filter((i) => (kind === 'all' || i.kind === kind) && (!q || i.name.toLowerCase().includes(q) || i.summary.toLowerCase().includes(q)));
  }, [items, query, kind]);

  return (
    <section className="section-padding pb-24" aria-labelledby="api-index">
      <div className="max-w-6xl mx-auto">
        <h2 id="api-index" className="text-3xl font-bold mb-2">API index</h2>
        <p className="text-secondary text-sm mb-6 max-w-3xl">
          Generated from the published <code className="font-mono text-cyan-200">{api.package} {api.version}</code> wheel on {api.generated}:
          every public name in <code className="font-mono text-cyan-200">qector_decoder_v3</code>, with the signature Python reports and the first paragraph of its docstring.
          {' '}{items.length} names.
        </p>
        <div className="flex flex-wrap gap-3 mb-6">
          <label className="sr-only" htmlFor="api-q">Filter the API index</label>
          <input
            id="api-q"
            type="search"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Filter by name or description"
            className="flex-1 min-w-[14rem] bg-surface border border-gridline rounded-lg px-3 py-2 text-sm text-primary placeholder:text-muted-foreground focus:outline-none focus:border-cyan-300/50"
          />
          <div className="flex gap-1" role="group" aria-label="Kind">
            {['all', ...KINDS].map((k) => (
              <button key={k} type="button" aria-pressed={kind === k} onClick={() => setKind(k)}
                className={`px-3 py-2 rounded-lg text-xs font-semibold capitalize border ${kind === k ? 'border-cyan-300/50 text-cyan-300 bg-cyan-300/10' : 'border-gridline text-secondary hover:text-primary'}`}>
                {({ all: 'All', class: 'Classes', function: 'Functions', module: 'Modules' } as Record<string, string>)[k]}
              </button>
            ))}
          </div>
        </div>
        <ul className="space-y-3">
          {shown.map((i) => (
            <li key={i.name} className="bg-[#0b1329]/40 border border-slate-800/80 rounded-2xl p-4">
              <div className="flex flex-wrap items-baseline gap-x-3 gap-y-1">
                <span className="text-[10px] uppercase tracking-wider font-semibold text-muted-foreground">{i.kind}</span>
                <code className="font-mono text-cyan-300 text-sm break-all">{i.name}<span className="text-secondary">{i.signature}</span></code>
              </div>
              {i.summary && <p className="text-secondary text-sm mt-2 leading-relaxed">{i.summary}</p>}
              {i.methods.length > 0 && (
                <details className="mt-2">
                  <summary className="text-xs text-muted-foreground cursor-pointer hover:text-cyan-300">{i.methods.length} public methods</summary>
                  <ul className="mt-2 grid md:grid-cols-2 gap-x-6 gap-y-1">
                    {i.methods.map((m) => (
                      <li key={m.name}><code className="font-mono text-xs text-primary break-all">{m.name}<span className="text-muted-foreground">{m.signature}</span></code></li>
                    ))}
                  </ul>
                </details>
              )}
            </li>
          ))}
          {shown.length === 0 && <li className="text-muted-foreground text-sm">No names match.</li>}
        </ul>
      </div>
    </section>
  );
}
